(async () => {
  const f = (path, method = 'GET', data) => wp.apiFetch({ path, method, data }).catch((e) => ({ error: e.code || e.message, status: e.data && e.data.status }));
  const out = {};
  for (const c of ['US:CA', 'GB', 'AE', 'SA', 'OM', 'YE', 'EG']) {
    await f('/wc-analytics/settings/general/woocommerce_default_country', 'POST', { value: c });
    const ext = await f('/wc-admin/onboarding/free-extensions');
    out[c] = Array.isArray(ext) ? ext.map((b) => [b.key, (b.plugins || []).map((p) => p.key)]) : ext;
  }
  await f('/wc-analytics/settings/general/woocommerce_default_country', 'POST', { value: 'US:CA' });
  return out;
})()
